{"tool": "submit_job", "args": {"source": "import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import crypto from 'node:crypto';

export async function gate({ referenceDir, submissionDir }) {
  const nonce = crypto.randomBytes(32).toString('hex');
  const resultFile = path.join(referenceDir, 'outcome-' + nonce + '.txt');
  const submissionFile = path.join(submissionDir, 'answer.mjs');
  const runner = [
    "import fs from 'node:fs';",
    "import assert from 'node:assert/strict';",
    "import { pathToFileURL } from 'node:url';",
    "const deepStrictEqual = assert.deepStrictEqual;",
    "const resultFile = " + JSON.stringify(resultFile) + ";",
    "const nonce = " + JSON.stringify(nonce) + ";",
    "const submissionFile = " + JSON.stringify(submissionFile) + ";",
    "function fail(reason) {",
    "  try { fs.writeFileSync(resultFile, 'FAIL ' + String(reason)); } catch {}",
    "}",
    "try {",
    "  const mod = await import(pathToFileURL(submissionFile).href);",
    "  const dedupeSorted = mod.dedupeSorted;",
    "  if (typeof dedupeSorted !== 'function') { fail('dedupeSorted not a function'); }",
    "  else {",
    "    let completed = 0;",
    "    const test = (name, fn) => { fn(); completed++; };",
    "    test('empty array', () => { deepStrictEqual(dedupeSorted([]), []); });",
    "    test('single element', () => { deepStrictEqual(dedupeSorted([5]), [5]); });",
    "    test('no duplicates', () => { deepStrictEqual(dedupeSorted([1, 2, 3]), [1, 2, 3]); });",
    "    test('all duplicates', () => { deepStrictEqual(dedupeSorted([4, 4, 4, 4]), [4]); });",
    "    test('duplicates at the start', () => { deepStrictEqual(dedupeSorted([1, 1, 2, 3]), [1, 2, 3]); });",
    "    test('duplicates at the end', () => { deepStrictEqual(dedupeSorted([1, 2, 3, 3]), [1, 2, 3]); });",
    "    test('negative numbers with duplicates', () => { deepStrictEqual(dedupeSorted([-3, -3, -1, 0, 0, 2]), [-3, -1, 0, 2]); });",
    "    test('randomized property check against a reference oracle', () => {",
    "      for (let trial = 0; trial < 20; trial++) {",
    "        const len = 1 + Math.floor(Math.random() * 10);",
    "        const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);",
    "        const expected = [...new Set(arr)];",
    "        deepStrictEqual(dedupeSorted(arr), expected);",
    "      }",
    "    });",
    "    if (completed !== 8) { fail('incomplete ' + completed); }",
    "    else { fs.writeFileSync(resultFile, 'PASS ' + nonce); }",
    "  }",
    "} catch (e) {",
    "  fail(e && e.stack ? e.stack : e);",
    "}"
  ].join("\n");

  await new Promise((resolve) => {
    const child = spawn(process.execPath, ['--input-type=module', '--no-warnings', '-'], {
      stdio: ['pipe', 'pipe', 'pipe']
    });
    const timer = setTimeout(() => { try { child.kill('SIGKILL'); } catch {} }, 8000);
    child.on('error', () => { clearTimeout(timer); resolve(); });
    child.on('close', () => { clearTimeout(timer); resolve(); });
    child.stdin.on('error', () => {});
    child.stdout.resume();
    child.stderr.resume();
    child.stdin.write(runner);
    child.stdin.end();
  });

  let outcome;
  try {
    outcome = fs.readFileSync(resultFile, 'utf8');
  } catch {
    return { accept: false, reason: 'suite did not run to completion' };
  }
  if (outcome === 'PASS ' + nonce) {
    return { accept: true, reason: 'all pinned tests passed' };
  }
  return { accept: false, reason: String(outcome).slice(0, 240) };
}
